    }

    const requiredFields = ["productId", "quantity"];

    const types = {
        productId: ["integer"],
        quantity: ["integer"]
    };

    requiredFields.forEach(function (field) {
        if (!(field in item)) {
            errors.push(label + ": отсутствует обязательное поле '" + field + "'.");
        }
    });

    Object.keys(types).forEach(function (field) {
        if (field in item) {
            const actualType = getType(item[field]);
            const allowedTypes = types[field];

            if (!typeMatches(actualType, allowedTypes)) {
                errors.push(
                    label + ": поле '" + field + "' должно быть " +
                    allowedTypes.join(" / ") + ", получено " + actualType + "."
                );
            }
        }
    });

    return errors;
}

function validateCart(item, label, requireAllFields) {
