            ).to.be.true;
        });

        if (Array.isArray(responseBody)) {
            pm.test("[Позитивный] carts: корзины имеют корректную структуру", function () {
                let errors = [];

                if (responseBody.length === 0) {
                    errors.push("Список корзин пуст.");
                }

                responseBody.slice(0, 10).forEach(function (item, index) {
                    errors = errors.concat(validateCart(item, "carts[" + index + "]", true));
                });

                pm.expect(errors.length, errors.join(" ")).to.equal(0);
            });
        }
    }

    // POST /carts
    if (method === "POST" && isCartsCollection) {
        pm.test("[Позитивный] carts: корзина создана", function () {
            const errors = validateCart(responseBody, "Ответ на создание корзины", false);

            pm.expect(errors.length, errors.join(" ")).to.equal(0);
        });
    }

    // GET/PUT/PATCH/DELETE /carts/{id}
    if (cartIdMatch) {
        const expectedId = Number(cartIdMatch[1]);

        pm.test("[Позитивный] carts: id в ответе совпадает с запрошенным", function () {
            pm.expect(
                responseBody && responseBody.id,
                "Тело ответа: " + short(responseBody)
            ).to.equal(expectedId);
        });

        if (method === "GET") {
